async function passkeySignInEmailFirst(email: string) {
  // 1) Get options
  const options = await (await fetch('/auth/passkeys/assert', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({ email, userVerification: 'required' })
  })).json(); // PasskeyAssertionOptionsResponse

  // 2) WebAuthn prompt
  const cred = await navigator.credentials.get({ publicKey: options.publicKey });

  // 3) Verify (send clientDataJSON, authenticatorData, signature, userHandle, id)
  const verify = await (await fetch('/auth/passkeys/assert/verify', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({
      challengeToken: options.challengeToken,
      credential: {
        id: cred.id,
        rawId: btoa(String.fromCharCode(...new Uint8Array(cred.rawId))),
        type: cred.type,
        response: {
          clientDataJSON: btoa(String.fromCharCode(...new Uint8Array(cred.response.clientDataJSON))),
          authenticatorData: btoa(String.fromCharCode(...new Uint8Array(cred.response.authenticatorData))),
          signature: btoa(String.fromCharCode(...new Uint8Array(cred.response.signature))),
          userHandle: cred.response.userHandle ? btoa(String.fromCharCode(...new Uint8Array(cred.response.userHandle))) : null
        }
      }
    })
  })).json(); // typically { loginTx: "..." }

  return verify;
}

async function exchange(handle) {
  const r = await fetch('/auth/token', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify(handle) // e.g., { grantType:'loginTx', loginTx:'...' }
  });
  const body = await r.json();
  if (body.nextStep === 'pickOrg') {
    const orgId = await showOrgPicker(body.memberships);
    const r2 = await fetch('/auth/token', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ ...handle, orgId })
    });
    return r2.json();
  }
  return body; // tokens
}

